SET search_path TO lms, extensions;

-- ============================================================
-- Fix: Only insert users into lms.users once their email is verified.
-- This prevents typo emails from cluttering the public schema.
-- ============================================================

CREATE OR REPLACE FUNCTION lms.handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER
SET search_path = lms
AS $$
BEGIN
  -- Guard: skip if email is null
  IF NEW.email IS NULL THEN
    RETURN NEW;
  END IF;

  -- Guard: ONLY insert into public schema if the email is confirmed!
  -- This prevents typo emails (unverified users) from cluttering our app data.
  IF NEW.email_confirmed_at IS NULL THEN
    RETURN NEW;
  END IF;

  -- Insert the user into our public schema.
  -- ON CONFLICT DO NOTHING ensures this safely handles the transition 
  -- from INSERT to UPDATE without duplicating.
  INSERT INTO lms.users (id, email, full_name, role)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', NULL),
    COALESCE(NEW.raw_user_meta_data->>'role', 'learner')
  )
  ON CONFLICT (id) DO NOTHING;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'handle_new_user failed for user %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;

-- Drop the old trigger that only fired on INSERT
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;

-- Recreate the trigger to fire on BOTH INSERT and UPDATE.
-- When a user requests an OTP, it's an INSERT (but unconfirmed, so the function exits).
-- When they enter the 6-digit code, it's an UPDATE (confirmed, so the function inserts them).
CREATE TRIGGER on_auth_user_created
  AFTER INSERT OR UPDATE ON auth.users
  FOR EACH ROW EXECUTE PROCEDURE lms.handle_new_user();
